// GENERATED by scripts/build-content.mjs from content/. Do not edit.
export interface Heading {
  depth: 2 | 3;
  id: string;
  text: string;
}

export interface WorkMeta {
  /** True once the case study at /work/<slug> is written and built. */
  published: boolean;
  role: string;
  hardest: string;
  outcomes: string[];
  /** The case study's body, compiled from Markdown. Empty until published. */
  html: string;
  headings: Heading[];
}

export interface Note {
  slug: string;
  number: string;
  title: string;
  date: string;
  summary: string;
  draft: boolean;
  minutes: number;
  html: string;
  headings: Heading[];
}

